package com.globaldefense.sso.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.session.FindByIndexNameSessionRepository;
import org.springframework.session.data.redis.RedisIndexedSessionRepository;
import org.springframework.session.data.redis.RedisSessionRepository;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/security/sessions")
public class RemoteSessionTerminationController {

    private final RedisIndexedSessionRepository sessionRepository;

    public RemoteSessionTerminationController(RedisIndexedSessionRepository sessionRepository) {
        this.sessionRepository = sessionRepository;
    }

    @DeleteMapping("/{targetSessionId}")
    public ResponseEntity<String> terminateSession(
            @PathVariable String targetSessionId,
            Authentication authentication) {
        var session = sessionRepository.findById(targetSessionId);
        if (session == null) {
            return ResponseEntity.notFound().build();
        }
        String sessionOwner = session.getAttribute(FindByIndexNameSessionRepository.PRINCIPAL_NAME_INDEX_NAME);
        if (sessionOwner == null || !sessionOwner.equals(authentication.getName())) {
            throw new AccessDeniedException("Cannot terminate a session belonging to another user");
        }
        sessionRepository.deleteById(targetSessionId);
        return ResponseEntity.ok("Session revoked successfully");
    }
}
